modelantwoord:
PUT flights_fixed
{
  "settings": { "analysis": { "analyzer": { "case-analyzer": {
    "type": "custom", "tokenizer": "standard", "filter": ["lowercase"] } } } },
  "mappings": { "properties": { "Carrier": { "type": "text", "analyzer": "case-analyzer" } } }
}

POST flights_fixed/_analyze
{ "analyzer": "case-analyzer", "text": "JetStar" }

POST _reindex
{ "source": { "index": "kibana_sample_data_flights" }, "dest": { "index": "flights_fixed" } }

GET flights_fixed/_mapping

DELETE flights_fixed

PUT kibana_flights
{
  "settings": { "analysis": { "analyzer": { "case-analyzer": {
    "type": "custom", "tokenizer": "standard", "filter": ["lowercase"] } } } },
  "mappings": {
    "dynamic_templates": [
      { "strings_as_keyword": {
          "match_mapping_type": "string",
          "match": "*",
          "unmatch": "Carrier",
          "mapping": { "type": "keyword" }
      } }
    ],
    "properties": { "Carrier": { "type": "text", "analyzer": "case-analyzer" } }
  }
}

POST _reindex
{ "source": { "index": "kibana_sample_data_flights" }, "dest": { "index": "kibana_flights" } }

GET kibana_flights/_mapping

PUT _cluster/settings
{
  "persistent": { "cluster": { "remote": { "cluster2_remote": {
    "mode": "sniff", "seeds": ["node5:9304"], "skip_unavailable": false
  } } } }
}

GET kibana_sample_data_flights,cluster2_remote:kibana_sample_data_flights/_search
{
  "query": { "term": { "Origin": "Tokyo Haneda International Airport" } },
  "aggs": { "avg_ticket_price": { "avg": { "field": "AvgTicketPrice" } } }
}

PUT _ingest/pipeline/flightstatus_pipeline
{
  "processors": [
    { "script": { "source": "if (ctx.FlightDelay == true) { ctx['Flight Status'] = 'Delayed'; } else if (ctx.Cancelled == true) { ctx['Flight Status'] = 'Cancelled'; } else { ctx['Flight Status'] = 'On time'; }" } },
    { "remove": { "field": ["FlightDelay", "Cancelled"] } }
  ]
}

PUT flights_with_status

POST _reindex
{
  "source": { "index": "kibana_sample_data_flights" },
  "dest": { "index": "flights_with_status", "pipeline": "flightstatus_pipeline" }
}

GET flights_with_status/_search?size=1
